  "Access events": "ಪ್ರವೇಶ ಘಟನೆಗಳು",
  "The workflow allows no further status changes from here.": "ಕಾರ್ಯಪ್ರವಾಹವು ಇಲ್ಲಿಂದ ಮುಂದೆ ಯಾವುದೇ ಸ್ಥಿತಿ ಬದಲಾವಣೆಗೆ ಅವಕಾಶ ನೀಡುವುದಿಲ್ಲ.",
  "This will close the case. Open tasks are not closed automatically. The case can be reopened if the workflow allows.": "ಇದು ಪ್ರಕರಣವನ್ನು ಮುಕ್ತಾಯಗೊಳಿಸುತ್ತದೆ. ತೆರೆದ ಕಾರ್ಯಗಳು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಮುಕ್ತಾಯಗೊಳ್ಳುವುದಿಲ್ಲ. ಕಾರ್ಯಪ್ರವಾಹ ಅನುಮತಿಸಿದರೆ ಪ್ರಕರಣವನ್ನು ಮತ್ತೆ ತೆರೆಯಬಹುದು.",
