  "Officer-written summary. The original statement and transcripts are kept separately and are not changed by this field.": "ಅಧಿಕಾರಿ ಬರೆದ ಸಾರಾಂಶ. ಮೂಲ ಹೇಳಿಕೆ ಮತ್ತು ಪ್ರತಿಲೇಖನಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಇರಿಸಲಾಗಿದೆ ಮತ್ತು ಈ ಕ್ಷೇತ್ರದಿಂದ ಅವು ಬದಲಾಗುವುದಿಲ್ಲ.",
