  "Delete file": "ಫೈಲ್ ಅಳಿಸಿ",
  "This change will be applied to each selected case individually. Cases where the change is not allowed by the workflow or your permissions will be skipped and reported. Every change is recorded in the audit history.": "ಈ ಬದಲಾವಣೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿದ ಪ್ರತಿಯೊಂದು ಪ್ರಕರಣಕ್ಕೂ ಪ್ರತ್ಯೇಕವಾಗಿ ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ. ಕಾರ್ಯಪ್ರವಾಹ ಅಥವಾ ನಿಮ್ಮ ಅನುಮತಿಗಳು ಬದಲಾವಣೆಗೆ ಅವಕಾಶ ನೀಡದ ಪ್ರಕರಣಗಳನ್ನು ಬಿಟ್ಟುಬಿಟ್ಟು ವರದಿ ಮಾಡಲಾಗುತ್ತದೆ. ಪ್ರತಿಯೊಂದು ಬದಲಾವಣೆಯೂ ಲೆಕ್ಕಪರಿಶೋಧನಾ ಇತಿಹಾಸದಲ್ಲಿ ದಾಖಲಾಗುತ್ತದೆ.",
