  "Select all cases on this page": "ಈ ಪುಟದ ಎಲ್ಲಾ ಪ್ರಕರಣಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ",
  "No further moves allowed": "ಮುಂದಿನ ಸ್ಥಳಾಂತರಕ್ಕೆ ಅವಕಾಶವಿಲ್ಲ",
  "If you choose a closing status, the case will be marked closed. You can reopen it later if the workflow allows.": "ನೀವು ಮುಕ್ತಾಯದ ಸ್ಥಿತಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿದರೆ, ಪ್ರಕರಣವನ್ನು ಮುಕ್ತಾಯಗೊಂಡಿದೆ ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ. ಕಾರ್ಯಪ್ರವಾಹ ಅನುಮತಿಸಿದರೆ ನಂತರ ಅದನ್ನು ಮತ್ತೆ ತೆರೆಯಬಹುದು.",
  "Move to…": "ಇಲ್ಲಿಗೆ ಸರಿಸಿ…",
  "Move": "ಸರಿಸಿ",
  "Search tasks": "ಕಾರ್ಯಗಳನ್ನು ಹುಡುಕಿ",
  "Sort": "ವಿಂಗಡಿಸಿ",
  "Due date": "ಗಡುವು ದಿನಾಂಕ",
  "Recently updated": "ಇತ್ತೀಚೆಗೆ ನವೀಕರಿಸಿದವು",
  "Newest": "ಹೊಸದು",
