  "Quick filters": "ತ್ವರಿತ ಫಿಲ್ಟರ್‌ಗಳು",
  "Search title or case reference": "ಶೀರ್ಷಿಕೆ ಅಥವಾ ಪ್ರಕರಣದ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆಯನ್ನು ಹುಡುಕಿ",
  "Type": "ಪ್ರಕಾರ",
  "Mark complete": "ಪೂರ್ಣಗೊಂಡಿದೆ ಎಂದು ಗುರುತಿಸಿ",
