  "No description.": "ವಿವರಣೆ ಇಲ್ಲ.",
  "Show edit form": "ಸಂಪಾದನಾ ನಮೂನೆಯನ್ನು ತೋರಿಸಿ",
  "No comments yet.": "ಇನ್ನೂ ಯಾವುದೇ ಅಭಿಪ್ರಾಯಗಳಿಲ್ಲ.",
  "Your role can view this task but not comment on it.": "ನಿಮ್ಮ ಪಾತ್ರವು ಈ ಕಾರ್ಯವನ್ನು ವೀಕ್ಷಿಸಬಹುದು ಆದರೆ ಅದರ ಮೇಲೆ ಅಭಿಪ್ರಾಯ ನೀಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Mark this task as complete? It can be reopened later.": "ಈ ಕಾರ್ಯವನ್ನು ಪೂರ್ಣಗೊಂಡಿದೆ ಎಂದು ಗುರುತಿಸಬೇಕೇ? ನಂತರ ಅದನ್ನು ಮತ್ತೆ ತೆರೆಯಬಹುದು.",
  "Complete task": "ಕಾರ್ಯವನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ",
  "Reopen task": "ಕಾರ್ಯವನ್ನು ಮತ್ತೆ ತೆರೆಯಿರಿ",
  "Edit task": "ಕಾರ್ಯವನ್ನು ಸಂಪಾದಿಸಿ",
  "Changes are recorded in the activity history and audit log.": "ಬದಲಾವಣೆಗಳನ್ನು ಚಟುವಟಿಕೆ ಇತಿಹಾಸ ಮತ್ತು ಲೆಕ್ಕಪರಿಶೋಧನಾ ದಾಖಲೆಯಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.",
  "Activity": "ಚಟುವಟಿಕೆ",
  "No activity yet": "ಇನ್ನೂ ಯಾವುದೇ ಚಟುವಟಿಕೆ ಇಲ್ಲ",
  "Your account is not linked to a station, so tasks must be linked to a case you can access. No accessible cases are available.": "ನಿಮ್ಮ ಖಾತೆಯು ಯಾವುದೇ ಠಾಣೆಗೆ ಸಂಪರ್ಕಗೊಂಡಿಲ್ಲ, ಆದ್ದರಿಂದ ಕಾರ್ಯಗಳನ್ನು ನೀವು ಪ್ರವೇಶಿಸಬಹುದಾದ ಪ್ರಕರಣಕ್ಕೆ ಸಂಪರ್ಕಿಸಬೇಕು. ಪ್ರವೇಶಿಸಬಹುದಾದ ಯಾವುದೇ ಪ್ರಕರಣಗಳು ಲಭ್ಯವಿಲ್ಲ.",
  "The requested case was not found or you do not have access to it. The task will not be linked unless you choose a case.": "ವಿನಂತಿಸಿದ ಪ್ರಕರಣ ಕಂಡುಬಂದಿಲ್ಲ ಅಥವಾ ಅದಕ್ಕೆ ನಿಮಗೆ ಪ್ರವೇಶವಿಲ್ಲ. ನೀವು ಪ್ರಕರಣವನ್ನು ಆಯ್ಕೆಮಾಡದ ಹೊರತು ಕಾರ್ಯವನ್ನು ಸಂಪರ್ಕಿಸಲಾಗುವುದಿಲ್ಲ.",
  "No station assigned": "ಯಾವುದೇ ಠಾಣೆ ನಿಯೋಜಿಸಲಾಗಿಲ್ಲ",
  "Titles appear in notifications — keep them generic and avoid statement details or personal information.": "ಶೀರ್ಷಿಕೆಗಳು ಸೂಚನೆಗಳಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ — ಅವುಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿರಿಸಿ ಮತ್ತು ಹೇಳಿಕೆಯ ವಿವರಗಳು ಅಥವಾ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ತಪ್ಪಿಸಿ.",
  "Low": "ಕಡಿಮೆ",
  "Medium": "ಮಧ್ಯಮ",
  "High": "ಹೆಚ್ಚು",
  "Urgent": "ತುರ್ತು",
  "Linked case": "ಸಂಪರ್ಕಿತ ಪ್ರಕರಣ",
  "No linked case": "ಸಂಪರ್ಕಿತ ಪ್ರಕರಣವಿಲ್ಲ",
  "Only active staff in the task's station are listed.": "ಕಾರ್ಯದ ಠಾಣೆಯ ಸಕ್ರಿಯ ಸಿಬ್ಬಂದಿಯನ್ನು ಮಾತ್ರ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ.",
  "Reminder": "ಜ್ಞಾಪನೆ",
  "An in-app reminder is sent to the assignee at this time (or 24h before the due date).": "ಈ ಸಮಯದಲ್ಲಿ (ಅಥವಾ ಗಡುವು ದಿನಾಂಕಕ್ಕೆ 24 ಗಂ ಮೊದಲು) ನಿಯೋಜಿತರಿಗೆ ಅಪ್ಲಿಕೇಶನ್‌ನೊಳಗೆ ಜ್ಞಾಪನೆಯನ್ನು ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
  "Assign": "ನಿಯೋಜಿಸಿ",
  "Add a comment": "ಅಭಿಪ್ರಾಯ ಸೇರಿಸಿ",
