  "Where cases you can access currently stand.": "ನೀವು ಪ್ರವೇಶಿಸಬಹುದಾದ ಪ್ರಕರಣಗಳು ಪ್ರಸ್ತುತ ಯಾವ ಹಂತದಲ್ಲಿವೆ.",
  "Filtered by your selection.": "ನಿಮ್ಮ ಆಯ್ಕೆಯಂತೆ ಫಿಲ್ಟರ್ ಮಾಡಲಾಗಿದೆ.",
  "The most recently updated cases you can access, with the next action for each.": "ನೀವು ಪ್ರವೇಶಿಸಬಹುದಾದ ಇತ್ತೀಚೆಗೆ ನವೀಕರಿಸಿದ ಪ್ರಕರಣಗಳು, ಪ್ರತಿಯೊಂದರ ಮುಂದಿನ ಕ್ರಮದೊಂದಿಗೆ.",
