  "No speech was recognised in this recording. Check the audio, or transcribe manually.": "ಈ ರೆಕಾರ್ಡಿಂಗ್‌ನಲ್ಲಿ ಯಾವುದೇ ಮಾತು ಗುರುತಿಸಲಾಗಿಲ್ಲ. ಆಡಿಯೋವನ್ನು ಪರಿಶೀಲಿಸಿ, ಅಥವಾ ಕೈಯಾರೆ ಪ್ರತಿಲೇಖಿಸಿ.",
