  "Abandoned": "ಕೈಬಿಡಲಾಗಿದೆ",
  "Staff or the speaker types the account in their own words.": "ಸಿಬ್ಬಂದಿ ಅಥವಾ ಹೇಳಿಕೆದಾರರು ಅವರದೇ ಮಾತುಗಳಲ್ಲಿ ಹೇಳಿಕೆಯನ್ನು ಟೈಪ್ ಮಾಡುತ್ತಾರೆ.",
  "Record the spoken account (requires consent). Staff transcribe it afterwards.": "ಮೌಖಿಕ ಹೇಳಿಕೆಯನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡಿ (ಸಮ್ಮತಿ ಅಗತ್ಯ). ಸಿಬ್ಬಂದಿ ನಂತರ ಅದನ್ನು ಪ್ರತಿಲೇಖಿಸುತ್ತಾರೆ.",
  "Record audio and video (requires consent).": "ಆಡಿಯೋ ಮತ್ತು ವೀಡಿಯೋ ರೆಕಾರ್ಡ್ ಮಾಡಿ (ಸಮ್ಮತಿ ಅಗತ್ಯ).",
  "Staff write down the account on the speaker's behalf and read it back.": "ಸಿಬ್ಬಂದಿ ಹೇಳಿಕೆದಾರರ ಪರವಾಗಿ ಹೇಳಿಕೆಯನ್ನು ಬರೆದುಕೊಂಡು ಅವರಿಗೆ ಓದಿ ಹೇಳುತ್ತಾರೆ.",
  "For people unable to read, write, hear or use the standard workflow — e.g. with an interpreter or sign-language support.": "ಓದಲು, ಬರೆಯಲು, ಕೇಳಲು ಅಥವಾ ಪ್ರಮಾಣಿತ ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಬಳಸಲು ಸಾಧ್ಯವಾಗದ ವ್ಯಕ್ತಿಗಳಿಗಾಗಿ — ಉದಾ. ದುಭಾಷಿ ಅಥವಾ ಸಂಜ್ಞಾ ಭಾಷೆಯ ಬೆಂಬಲದೊಂದಿಗೆ.",
  "Continue to recording": "ರೆಕಾರ್ಡಿಂಗ್‌ಗೆ ಮುಂದುವರಿಯಿರಿ",
