  "Browse statements, transcripts, drafts, reviews, notes, attachments and audit history you are authorized to see. Lists show metadata only; open a record to view its content (access is logged).": "ನೀವು ನೋಡಲು ಅಧಿಕಾರ ಹೊಂದಿರುವ ಹೇಳಿಕೆಗಳು, ಪ್ರತಿಲೇಖನಗಳು, ಕರಡುಗಳು, ಪರಿಶೀಲನೆಗಳು, ಟಿಪ್ಪಣಿಗಳು, ಲಗತ್ತುಗಳು ಮತ್ತು ಲೆಕ್ಕಪರಿಶೋಧನಾ ಇತಿಹಾಸವನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ. ಪಟ್ಟಿಗಳು ಮೆಟಾಡೇಟಾವನ್ನು ಮಾತ್ರ ತೋರಿಸುತ್ತವೆ; ವಿಷಯವನ್ನು ನೋಡಲು ದಾಖಲೆಯನ್ನು ತೆರೆಯಿರಿ (ಪ್ರವೇಶವನ್ನು ದಾಖಲಿಸಲಾಗುತ್ತದೆ).",
