  "Your role does not include access to case records, so case reports are not available. Technical and security activity is available in the Records audit log.": "ನಿಮ್ಮ ಪಾತ್ರವು ಪ್ರಕರಣ ದಾಖಲೆಗಳಿಗೆ ಪ್ರವೇಶವನ್ನು ಒಳಗೊಂಡಿಲ್ಲ, ಆದ್ದರಿಂದ ಪ್ರಕರಣ ವರದಿಗಳು ಲಭ್ಯವಿಲ್ಲ. ತಾಂತ್ರಿಕ ಮತ್ತು ಭದ್ರತಾ ಚಟುವಟಿಕೆಯು ದಾಖಲೆಗಳ ಲೆಕ್ಕಪರಿಶೋಧನಾ ದಾಖಲೆಯಲ್ಲಿ ಲಭ್ಯವಿದೆ.",
