  "Workload figures describe allocation of work, not individual performance. Small counts may still identify individual cases; share exports only with authorized recipients.": "ಕಾರ್ಯಭಾರದ ಅಂಕಿಅಂಶಗಳು ಕೆಲಸದ ಹಂಚಿಕೆಯನ್ನು ವಿವರಿಸುತ್ತವೆ, ವೈಯಕ್ತಿಕ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನಲ್ಲ. ಸಣ್ಣ ಎಣಿಕೆಗಳು ಸಹ ವೈಯಕ್ತಿಕ ಪ್ರಕರಣಗಳನ್ನು ಗುರುತಿಸಬಹುದು; ರಫ್ತುಗಳನ್ನು ಅಧಿಕೃತ ಸ್ವೀಕರಿಸುವವರೊಂದಿಗೆ ಮಾತ್ರ ಹಂಚಿಕೊಳ್ಳಿ.",
