  "Works assigned cases: statements, drafts, reviews and tasks.": "ನಿಯೋಜಿತ ಪ್ರಕರಣಗಳ ಮೇಲೆ ಕೆಲಸ ಮಾಡುತ್ತಾರೆ: ಹೇಳಿಕೆಗಳು, ಕರಡುಗಳು, ಪರಿಶೀಲನೆಗಳು ಮತ್ತು ಕಾರ್ಯಗಳು.",
  "Captures reports and prepares drafts. Cannot complete reviews.": "ವರದಿಗಳನ್ನು ದಾಖಲಿಸುತ್ತಾರೆ ಮತ್ತು ಕರಡುಗಳನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ. ಪರಿಶೀಲನೆಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Inspects permitted cases and audit records without editing.": "ಅನುಮತಿಸಿದ ಪ್ರಕರಣಗಳು ಮತ್ತು ಲೆಕ್ಕಪರಿಶೋಧನಾ ದಾಖಲೆಗಳನ್ನು ಸಂಪಾದಿಸದೆ ಪರಿಶೀಲಿಸುತ್ತಾರೆ.",
