  "The user is signed out everywhere and cannot sign in until reactivated. Their records and history are kept.": "ಬಳಕೆದಾರರನ್ನು ಎಲ್ಲೆಡೆಯಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಲಾಗುತ್ತದೆ ಮತ್ತು ಮರುಸಕ್ರಿಯಗೊಳಿಸುವವರೆಗೆ ಸೈನ್ ಇನ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರ ದಾಖಲೆಗಳು ಮತ್ತು ಇತಿಹಾಸವನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.",
  "Deactivate account": "ಖಾತೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ",
  "Use when the person leaves the station. The user is signed out and cannot sign in. Records they created remain attributed to them. This can be reversed.": "ವ್ಯಕ್ತಿಯು ಠಾಣೆಯನ್ನು ತೊರೆದಾಗ ಬಳಸಿ. ಬಳಕೆದಾರರನ್ನು ಸೈನ್ ಔಟ್ ಮಾಡಲಾಗುತ್ತದೆ ಮತ್ತು ಸೈನ್ ಇನ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರು ರಚಿಸಿದ ದಾಖಲೆಗಳು ಅವರ ಹೆಸರಿನಲ್ಲೇ ಉಳಿಯುತ್ತವೆ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಬಹುದು.",
  "Security": "ಭದ್ರತೆ",
  "Unlock account": "ಖಾತೆಯನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಿ",
  "Clear the temporary lockout caused by repeated failed sign-ins.": "ಪುನರಾವರ್ತಿತ ವಿಫಲ ಸೈನ್-ಇನ್‌ಗಳಿಂದ ಉಂಟಾದ ತಾತ್ಕಾಲಿಕ ಲಾಕ್ ಅನ್ನು ತೆರವುಗೊಳಿಸಿ.",
  "Sign out {count} session": "{count} ಸೆಷನ್‌ನಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಿ",
  "Sign out {count} sessions": "{count} ಸೆಷನ್‌ಗಳಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಿ",
  "All active sessions for this user will end immediately.": "ಈ ಬಳಕೆದಾರರ ಎಲ್ಲಾ ಸಕ್ರಿಯ ಸೆಷನ್‌ಗಳು ತಕ್ಷಣ ಕೊನೆಗೊಳ್ಳುತ್ತವೆ.",
  "Change your own password under": "ನಿಮ್ಮ ಸ್ವಂತ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಇಲ್ಲಿ ಬದಲಾಯಿಸಿ:",
