  "Sequence reset": "ಕ್ರಮಸಂಖ್ಯೆ ಮರುಹೊಂದಿಕೆ",
  "Restart at 1 every calendar year": "ಪ್ರತಿ ಕ್ಯಾಲೆಂಡರ್ ವರ್ಷ 1 ರಿಂದ ಮತ್ತೆ ಪ್ರಾರಂಭಿಸಿ",
  "Never restart": "ಎಂದಿಗೂ ಮತ್ತೆ ಪ್ರಾರಂಭಿಸಬೇಡಿ",
  "Next reference preview:": "ಮುಂದಿನ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆಯ ಪೂರ್ವವೀಕ್ಷಣೆ:",
  "Format must include a {SEQ} token.": "ಸ್ವರೂಪವು {SEQ} ಟೋಕನ್ ಅನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.",
  "Save as a new template version?": "ಹೊಸ ಟೆಂಪ್ಲೇಟ್ ಆವೃತ್ತಿಯಾಗಿ ಉಳಿಸಬೇಕೇ?",
  "A new template version is created and used for new drafts. Existing drafts keep the version they were created with.": "ಹೊಸ ಟೆಂಪ್ಲೇಟ್ ಆವೃತ್ತಿಯನ್ನು ರಚಿಸಿ ಹೊಸ ಕರಡುಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ. ಈಗಿರುವ ಕರಡುಗಳು ಅವು ರಚಿಸಲ್ಪಟ್ಟ ಆವೃತ್ತಿಯನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Save new version": "ಹೊಸ ಆವೃತ್ತಿಯನ್ನು ಉಳಿಸಿ",
  "Template name": "ಟೆಂಪ್ಲೇಟ್ ಹೆಸರು",
