  "Save case workflow?": "ಪ್ರಕರಣ ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಉಳಿಸಬೇಕೇ?",
  "Save task workflow?": "ಕಾರ್ಯ ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಉಳಿಸಬೇಕೇ?",
  "The new workflow applies immediately to all status changes. Existing records keep their current status. This change is audited.": "ಹೊಸ ಕಾರ್ಯಪ್ರವಾಹವು ಎಲ್ಲಾ ಸ್ಥಿತಿ ಬದಲಾವಣೆಗಳಿಗೆ ತಕ್ಷಣ ಅನ್ವಯಿಸುತ್ತದೆ. ಈಗಿರುವ ದಾಖಲೆಗಳು ತಮ್ಮ ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ. ಈ ಬದಲಾವಣೆಯನ್ನು ಲೆಕ್ಕಪರಿಶೋಧಿಸಲಾಗುತ್ತದೆ.",
  "Save workflow": "ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಉಳಿಸಿ",
  "Workflow name": "ಕಾರ್ಯಪ್ರವಾಹದ ಹೆಸರು",
  "States": "ಸ್ಥಿತಿಗಳು",
  "The first state is used for new records. At least one state must be a “done” state. States in use cannot be removed.": "ಹೊಸ ದಾಖಲೆಗಳಿಗೆ ಮೊದಲ ಸ್ಥಿತಿಯನ್ನು ಬಳಸಲಾಗುತ್ತದೆ. ಕನಿಷ್ಠ ಒಂದು ಸ್ಥಿತಿಯು “ಪೂರ್ಣಗೊಂಡ” ಸ್ಥಿತಿಯಾಗಿರಬೇಕು. ಬಳಕೆಯಲ್ಲಿರುವ ಸ್ಥಿತಿಗಳನ್ನು ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "{count} in use": "{count} ಬಳಕೆಯಲ್ಲಿದೆ",
