  "{label} is in use and cannot be removed": "{label} ಬಳಕೆಯಲ್ಲಿದೆ ಮತ್ತು ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "Remove {label}": "{label} ತೆಗೆದುಹಾಕಿ",
  "Add state": "ಸ್ಥಿತಿ ಸೇರಿಸಿ",
  "Allowed transitions": "ಅನುಮತಿಸಲಾದ ಪರಿವರ್ತನೆಗಳು",
  "Rows are the current state; tick each state it may move to.": "ಸಾಲುಗಳು ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯಾಗಿವೆ; ಅದು ಸರಿಯಬಹುದಾದ ಪ್ರತಿಯೊಂದು ಸ್ಥಿತಿಯನ್ನು ಟಿಕ್ ಮಾಡಿ.",
  "Transition matrix: from state (rows) to state (columns)": "ಪರಿವರ್ತನಾ ಕೋಷ್ಟಕ: ಈ ಸ್ಥಿತಿಯಿಂದ (ಸಾಲುಗಳು) ಈ ಸ್ಥಿತಿಗೆ (ಕಾಲಂಗಳು)",
  "From ↓ / To →": "ಇಂದ ↓ / ಗೆ →",
  "Allow {from} to {to}": "{from} ನಿಂದ {to} ಗೆ ಅನುಮತಿಸಿ",
  "Save case workflow": "ಪ್ರಕರಣ ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಉಳಿಸಿ",
  "Save task workflow": "ಕಾರ್ಯ ಕಾರ್ಯಪ್ರವಾಹವನ್ನು ಉಳಿಸಿ",
  "No catalogue entries matched the statement.": "ಯಾವುದೇ ಪಟ್ಟಿಯ ನಮೂದುಗಳು ಹೇಳಿಕೆಗೆ ಹೊಂದಾಣಿಕೆಯಾಗಲಿಲ್ಲ.",
  "{added} new suggestion(s); {total} matched in total.": "{added} ಹೊಸ ಸಲಹೆ(ಗಳು); ಒಟ್ಟು {total} ಹೊಂದಾಣಿಕೆಯಾಗಿವೆ.",
  "Provision selected.": "ನಿಬಂಧನೆಯನ್ನು ಆಯ್ಕೆಮಾಡಲಾಗಿದೆ.",
  "Provision added and selected.": "ನಿಬಂಧನೆಯನ್ನು ಸೇರಿಸಿ ಆಯ್ಕೆಮಾಡಲಾಗಿದೆ.",
  "Provision rejected.": "ನಿಬಂಧನೆಯನ್ನು ತಿರಸ್ಕರಿಸಲಾಗಿದೆ.",
  "Decision undone.": "ನಿರ್ಧಾರವನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ.",
  "Saved as draft version {version}.": "ಕರಡು ಆವೃತ್ತಿ {version} ಆಗಿ ಉಳಿಸಲಾಗಿದೆ.",
  "The draft already lists these provisions.": "ಕರಡಿನಲ್ಲಿ ಈಗಾಗಲೇ ಈ ನಿಬಂಧನೆಗಳು ಪಟ್ಟಿಯಾಗಿವೆ.",
  "Provision updated.": "ನಿಬಂಧನೆಯನ್ನು ನವೀಕರಿಸಲಾಗಿದೆ.",
  "Provision added to the catalogue.": "ನಿಬಂಧನೆಯನ್ನು ಪಟ್ಟಿಗೆ ಸೇರಿಸಲಾಗಿದೆ.",
  "Provision reactivated.": "ನಿಬಂಧನೆಯನ್ನು ಮರುಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.",
  "Provision deactivated.": "ನಿಬಂಧನೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.",
  "Code": "ಸಂಕೇತ",
  "e.g. BNS 303(2)": "ಉದಾ. BNS 303(2)",
  "Section": "ಕಲಂ",
  "Act": "ಅಧಿನಿಯಮ",
  "Plain-language summary": "ಸರಳ ಭಾಷೆಯ ಸಾರಾಂಶ",
  "A short paraphrase, not the statutory text.": "ಸಂಕ್ಷಿಪ್ತ ಸರಳೀಕೃತ ವಿವರಣೆ, ಶಾಸನಬದ್ಧ ಪಠ್ಯವಲ್ಲ.",
  "Trigger phrases": "ಪ್ರಚೋದಕ ಪದಗುಚ್ಛಗಳು",
  "One per line or comma-separated, in any language. A suggestion appears when one of these phrases is in the statement.": "ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದು ಅಥವಾ ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿ, ಯಾವುದೇ ಭಾಷೆಯಲ್ಲಿ. ಈ ಪದಗುಚ್ಛಗಳಲ್ಲಿ ಒಂದು ಹೇಳಿಕೆಯಲ್ಲಿದ್ದಾಗ ಸಲಹೆ ಕಾಣಿಸುತ್ತದೆ.",
  "Source note": "ಮೂಲ ಟಿಪ್ಪಣಿ",
  "Where this entry was verified, or what still needs checking.": "ಈ ನಮೂದನ್ನು ಎಲ್ಲಿ ಪರಿಶೀಲಿಸಲಾಗಿದೆ, ಅಥವಾ ಇನ್ನೂ ಏನನ್ನು ಪರಿಶೀಲಿಸಬೇಕಾಗಿದೆ.",
  "Add provision": "ನಿಬಂಧನೆ ಸೇರಿಸಿ",
  "Legal provisions catalogue": "ಕಾನೂನು ನಿಬಂಧನೆಗಳ ಪಟ್ಟಿ",
  "The list the system draws suggestions from. Suggestions are only ever shown to officers, who decide what applies.": "ವ್ಯವಸ್ಥೆಯು ಸಲಹೆಗಳನ್ನು ಪಡೆಯುವ ಪಟ್ಟಿ. ಸಲಹೆಗಳನ್ನು ಅಧಿಕಾರಿಗಳಿಗೆ ಮಾತ್ರ ತೋರಿಸಲಾಗುತ್ತದೆ, ಯಾವುದು ಅನ್ವಯವಾಗುತ್ತದೆ ಎಂಬುದನ್ನು ಅವರೇ ನಿರ್ಧರಿಸುತ್ತಾರೆ.",
  "Verify every entry against the official text": "ಪ್ರತಿಯೊಂದು ನಮೂದನ್ನೂ ಅಧಿಕೃತ ಪಠ್ಯದೊಂದಿಗೆ ಹೋಲಿಸಿ ಪರಿಶೀಲಿಸಿ",
  "The starter entries are plain-language summaries prepared for demonstration. Before real use, an authorized person must check each code, title and summary against the official gazetted text.": "ಆರಂಭಿಕ ನಮೂದುಗಳು ಪ್ರಾತ್ಯಕ್ಷಿಕೆಗಾಗಿ ಸಿದ್ಧಪಡಿಸಿದ ಸರಳ ಭಾಷೆಯ ಸಾರಾಂಶಗಳು. ನೈಜ ಬಳಕೆಗೆ ಮೊದಲು, ಅಧಿಕೃತ ವ್ಯಕ್ತಿಯು ಪ್ರತಿಯೊಂದು ಸಂಕೇತ, ಶೀರ್ಷಿಕೆ ಮತ್ತು ಸಾರಾಂಶವನ್ನು ಅಧಿಕೃತ ರಾಜಪತ್ರ ಪಠ್ಯದೊಂದಿಗೆ ಹೋಲಿಸಿ ಪರಿಶೀಲಿಸಬೇಕು.",
  "Provisions ({count})": "ನಿಬಂಧನೆಗಳು ({count})",
  "Search provisions": "ನಿಬಂಧನೆಗಳನ್ನು ಹುಡುಕಿ",
  "Search code, title or summary": "ಸಂಕೇತ, ಶೀರ್ಷಿಕೆ ಅಥವಾ ಸಾರಾಂಶವನ್ನು ಹುಡುಕಿ",
  "No provisions found": "ಯಾವುದೇ ನಿಬಂಧನೆಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
  "{count} trigger phrase(s)": "{count} ಪ್ರಚೋದಕ ಪದಗುಚ್ಛ(ಗಳು)",
  "Inactive": "ನಿಷ್ಕ್ರಿಯ",
  "Deactivate": "ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ",
  "Reactivate": "ಮರುಸಕ್ರಿಯಗೊಳಿಸಿ",
  "Edit {code}": "{code} ಸಂಪಾದಿಸಿ",
