  "Raised": "ಕಳುಹಿಸಲಾಗಿದೆ",
  "Resolved": "ಪರಿಹರಿಸಲಾಗಿದೆ",
  "Response": "ಪ್ರತಿಕ್ರಿಯೆ",
  "Responses": "ಪ್ರತಿಕ್ರಿಯೆಗಳು",
